<?php
require __DIR__.'/../includes/bootstrap.php';require_admin();require __DIR__.'/../includes/upload.php';$id=(int)($_GET['id']??0);$error='';$c=['name'=>'','slug'=>'','profile_image'=>'','country'=>'','language'=>'','specialties'=>'','biography'=>'','youtube_url'=>'','website_url'=>'','social_links_json'=>'','video_ids_json'=>'','status'=>'draft'];
if($pdo&&$id){$s=$pdo->prepare('SELECT * FROM creators WHERE id=?');$s->execute([$id]);$c=$s->fetch()?:$c;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['name','slug','country','language','specialties','biography','youtube_url','website_url','social_links_json','video_ids_json','status'] as $k)$c[$k]=trim($_POST[$k]??'');if($c['name']===''||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$c['slug']))$error='Name and a valid lowercase slug are required.';foreach(['youtube_url','website_url'] as $field)if(!$error&&$c[$field]!==''&&!filter_var($c[$field],FILTER_VALIDATE_URL))$error='Enter valid official URLs.';foreach(['social_links_json','video_ids_json'] as $field)if(!$error&&$c[$field]!==''&&(!is_array(json_decode($c[$field],true))||json_last_error()!==JSON_ERROR_NONE))$error='Social links and video IDs must use valid JSON arrays.';try{if(!$error&&!empty($_FILES['profile_image']['name']))$c['profile_image']=save_upload($_FILES['profile_image'],'image');}catch(Throwable $e){$error=$e->getMessage();}if(!$error){try{$v=[$c['name'],$c['slug'],$c['profile_image'],$c['country'],$c['language'],$c['specialties'],$c['biography'],$c['youtube_url'],$c['website_url'],$c['social_links_json']?:null,$c['video_ids_json']?:null,$c['status']];if($id){$q=$pdo->prepare('UPDATE creators SET name=?,slug=?,profile_image=?,country=?,language=?,specialties=?,biography=?,youtube_url=?,website_url=?,social_links_json=?,video_ids_json=?,status=? WHERE id=?');$q->execute([...$v,$id]);log_admin_activity('creator_updated','Creator ID: '.$id);}else{$q=$pdo->prepare('INSERT INTO creators(name,slug,profile_image,country,language,specialties,biography,youtube_url,website_url,social_links_json,video_ids_json,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute($v);log_admin_activity('creator_created','Creator ID: '.$pdo->lastInsertId());}header('Location: creators.php');exit;}catch(Throwable $e){$error='Unable to save creator. Confirm the database migration is installed.';}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Creator</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1><?=e($id?'Edit Creator':'New Creator')?></h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data" class="card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><label>Name<input name="name" value="<?=e($c['name'])?>" required></label></p><p><label>Slug<input name="slug" value="<?=e($c['slug'])?>" required></label></p><p><label>Profile image<input type="file" name="profile_image" accept="image/jpeg,image/png,image/webp"></label></p><?php if($c['profile_image']):?><img src="../<?=e($c['profile_image'])?>" alt="Current profile" style="max-width:220px"><?php endif;?><p><label>Country<input name="country" value="<?=e($c['country'])?>"></label></p><p><label>Language<input name="language" value="<?=e($c['language'])?>"></label></p><p><label>ASMR specialties<input name="specialties" value="<?=e($c['specialties'])?>" placeholder="Whispering, tapping, roleplay"></label></p><p><label>Biography<textarea name="biography" rows="6"><?=e($c['biography'])?></textarea></label></p><p><label>Official YouTube URL<input type="url" name="youtube_url" value="<?=e($c['youtube_url'])?>"></label></p><p><label>Official website<input type="url" name="website_url" value="<?=e($c['website_url'])?>"></label></p><p><label>Social links JSON<textarea name="social_links_json" placeholder='["https://instagram.com/name"]'><?=e($c['social_links_json'])?></textarea></label></p><p><label>YouTube video IDs JSON<textarea name="video_ids_json" placeholder='["dQw4w9WgXcQ"]'><?=e($c['video_ids_json'])?></textarea></label></p><p><label>Status<select name="status"><?php foreach(['draft','published','archived'] as $status):?><option value="<?=$status?>" <?=$c['status']===$status?'selected':''?>><?=e(ucfirst($status))?></option><?php endforeach;?></select></label></p><button>Save creator</button> <a href="creators.php">Cancel</a></form></main></body></html>
